def prime_factors(num):
    factors = set()
    d = 2
    temp = num
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def check_condition(n):
    # D(n) = (n+2)(n^2 + 2n + 2)
    p1 = n + 2
    p2 = n**2 + 2*n + 2

    factors1 = prime_factors(p1)
    factors2 = prime_factors(p2)

    # Check if all prime factors are in {2, 5}
    is_valid_1 = all(f in {2, 5} for f in factors1)
    is_valid_2 = all(f in {2, 5} for f in factors2)

    return is_valid_1 and is_valid_2, factors1, factors2

print("Testing n=0 to n=7:")
results = {}
for n in range(8):
    is_valid, f1, f2 = check_condition(n)
    results[n] = (is_valid, f1, f2)

for n, (is_valid, f1, f2) in results.items():
    print(f"n={n}: Valid={is_valid}, Factors(n+2)={f1}, Factors(n^2+2n+2)={f2}")

