def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def v2(num):
    count = 0
    if num == 0:
        return float('inf')
    while num > 0 and num % 2 == 0:
        count += 1
        num //= 2
    return count

print(f"D(0) = {D(0)}, v2(D(0)) = {v2(D(0))}")
